const resolveViewColumns = (schemas) => {
    const resolve = (view) => {
        const columns = view.columns.map((column) => {
            let source = column.source;
            while (source) {
                const predicate = (col) => col.name === source.column;
                let sourceColumn = schemas[source.schema].tables
                    .find((table) => table.name === source.table)
                    ?.columns.find((element) => predicate(element));
                if (!sourceColumn) {
                    sourceColumn = schemas[source.schema].views
                        .find((view) => view.name === source.table)
                        ?.columns.find((element) => predicate(element));
                }
                if (!sourceColumn) {
                    sourceColumn = schemas[source.schema].materializedViews
                        .find((view) => view.name === source.table)
                        ?.columns.find((element) => predicate(element));
                }
                if (!sourceColumn) {
                    throw new Error(`Column ${source.schema}.${source.table}.${source.column} was not found..`);
                }
                if (sourceColumn.source) {
                    source = sourceColumn.source;
                }
                else {
                    return {
                        ...column,
                        isNullable: sourceColumn.isNullable,
                        reference: sourceColumn.reference,
                        references: sourceColumn.references,
                        isPrimaryKey: sourceColumn.isPrimaryKey,
                        indices: sourceColumn.indices,
                    };
                }
            }
            return column;
        });
        return {
            ...view,
            columns,
        };
    };
    const result = { ...schemas };
    for (const schema of Object.keys(result)) {
        result[schema].views = result[schema].views.map((element) => resolve(element));
        result[schema].materializedViews = result[schema].materializedViews.map((element) => resolve(element));
    }
    return result;
};
export default resolveViewColumns;
